window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1da64a4280390687"]={"versions": [{"id": "FIG-1da64a4280390687", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des BSW-Initialisierungsablaufs in der AUTOSAR Classic Platform. Das Diagramm ordnet sich architektonisch in die frühe Hochlaufphase (Startup Phase) der Basissoftware ein und modelliert die Interaktion zwischen dem Systemdienst-Modul ECU State Manager (<code>EcuM</code>) und dem Service-Schicht-Modul Default Error Tracer (<code>Det</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte BSW-Module (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code> («module»): Aufrufende Steuerinstanz des System State Managements mit durchgehender Aktivierungsphase während der Sequenz.\n</li><li><code>Det</code> («module»): Aufgerufenes Diagnose- und Tracing-Modul der Service-Schicht zur Erfassung von Entwicklungs- und Laufzeitfehlern.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen &amp; Interaktionsnachrichten (synchrone C-APIs):</p>\n<ul class=\"fig-list\"><li><code>Det_Init()</code>: Synchrone Initialisierungsfunktion, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Init()</code>: Expliziter synchroner Rücksprung (Reply Message) nach Abschluss der Initialisierungsroutine an <code>EcuM</code>.\n</li><li><code>Det_Start()</code>: Synchrone Startfunktion zur Aktivierung des regulären Tracing-Betriebs, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Start()</code>: Expliziter synchroner Rücksprung (Reply Message) an <code>EcuM</code>.\n</li></ul>\n<p class=\"fig-p\">Annotationen:</p>\n<ul class=\"fig-list\"><li>UML-Kommentar an <code>Det_Init()</code>: „Comment: Initialization of Default Error Tracer is performed synchronously“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller, synchroner Ablauf während des BSW-Hochlaufs:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt den synchronen Aufruf <code>Det_Init()</code> an das Modul <code>Det</code> ab.\n</li><li><code>Det</code> aktiviert seinen Ausführungsfokus und führt die interne Modulinitialisierung blockierend/synchron aus.\n</li><li>Nach Beendigung kehrt der Kontrollfluss über die Reply-Nachricht von <code>Det_Init()</code> zu <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>Det_Start()</code> auf <code>Det</code> auf.\n</li><li><code>Det</code> aktiviert erneut seinen Ausführungsfokus zur Scharfschaltung des DET-Betriebs.\n</li><li>Über den Reply-Pfeil von <code>Det_Start()</code> kehrt die Kontrolle synchron an <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die zweistufige Reihenfolge der Initialisierung: Vor dem operativen Start (<code>Det_Start</code>) muss zwingend die Initialisierung (<code>Det_Init</code>) vollständig und synchron abgeschlossen sein. Die synchrone Abwicklung stellt sicher, dass der Default Error Tracer einsatzbereit ist, bevor nachfolgende BSW-Module initialisiert werden und Entwicklungsfehler (<code>Det_ReportError</code>) melden können. Da der Aufruf im EcuM-Startup-Pfad blockierend erfolgt, dürfen <code>Det_Init</code> und <code>Det_Start</code> keine zeitintensiven Hardware-Operationen oder Polling-Schleifen ausführen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a36d47c907298b4", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des BSW-Initialisierungsablaufs in der AUTOSAR Classic Platform. Das Diagramm ordnet sich architektonisch in die frühe Hochlaufphase (Startup Phase) der Basissoftware ein und modelliert die Interaktion zwischen dem Systemdienst-Modul ECU State Manager (<code>EcuM</code>) und dem Service-Schicht-Modul Default Error Tracer (<code>Det</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte BSW-Module (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code> («module»): Aufrufende Steuerinstanz des System State Managements mit durchgehender Aktivierungsphase während der Sequenz.\n</li><li><code>Det</code> («module»): Aufgerufenes Diagnose- und Tracing-Modul der Service-Schicht zur Erfassung von Entwicklungs- und Laufzeitfehlern.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen &amp; Interaktionsnachrichten (synchrone C-APIs):</p>\n<ul class=\"fig-list\"><li><code>Det_Init()</code>: Synchrone Initialisierungsfunktion, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Init()</code>: Expliziter synchroner Rücksprung (Reply Message) nach Abschluss der Initialisierungsroutine an <code>EcuM</code>.\n</li><li><code>Det_Start()</code>: Synchrone Startfunktion zur Aktivierung des regulären Tracing-Betriebs, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Start()</code>: Expliziter synchroner Rücksprung (Reply Message) an <code>EcuM</code>.\n</li></ul>\n<p class=\"fig-p\">Annotationen:</p>\n<ul class=\"fig-list\"><li>UML-Kommentar an <code>Det_Init()</code>: „Comment: Initialization of Default Error Tracer is performed synchronously“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller, synchroner Ablauf während des BSW-Hochlaufs:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt den synchronen Aufruf <code>Det_Init()</code> an das Modul <code>Det</code> ab.\n</li><li><code>Det</code> aktiviert seinen Ausführungsfokus und führt die interne Modulinitialisierung blockierend/synchron aus.\n</li><li>Nach Beendigung kehrt der Kontrollfluss über die Reply-Nachricht von <code>Det_Init()</code> zu <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>Det_Start()</code> auf <code>Det</code> auf.\n</li><li><code>Det</code> aktiviert erneut seinen Ausführungsfokus zur Scharfschaltung des DET-Betriebs.\n</li><li>Über den Reply-Pfeil von <code>Det_Start()</code> kehrt die Kontrolle synchron an <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die zweistufige Reihenfolge der Initialisierung: Vor dem operativen Start (<code>Det_Start</code>) muss zwingend die Initialisierung (<code>Det_Init</code>) vollständig und synchron abgeschlossen sein. Die synchrone Abwicklung stellt sicher, dass der Default Error Tracer einsatzbereit ist, bevor nachfolgende BSW-Module initialisiert werden und Entwicklungsfehler (<code>Det_ReportError</code>) melden können. Da der Aufruf im EcuM-Startup-Pfad blockierend erfolgt, dürfen <code>Det_Init</code> und <code>Det_Start</code> keine zeitintensiven Hardware-Operationen oder Polling-Schleifen ausführen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-daca0b775c773d4c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des BSW-Initialisierungsablaufs in der AUTOSAR Classic Platform. Das Diagramm ordnet sich architektonisch in die frühe Hochlaufphase (Startup Phase) der Basissoftware ein und modelliert die Interaktion zwischen dem Systemdienst-Modul ECU State Manager (<code>EcuM</code>) und dem Service-Schicht-Modul Default Error Tracer (<code>Det</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte BSW-Module (Lebenslinien):</p>\n<ul class=\"fig-list\"><li><code>EcuM</code> («module»): Aufrufende Steuerinstanz des System State Managements mit durchgehender Aktivierungsphase während der Sequenz.\n</li><li><code>Det</code> («module»): Aufgerufenes Diagnose- und Tracing-Modul der Service-Schicht zur Erfassung von Entwicklungs- und Laufzeitfehlern.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen &amp; Interaktionsnachrichten (synchrone C-APIs):</p>\n<ul class=\"fig-list\"><li><code>Det_Init()</code>: Synchrone Initialisierungsfunktion, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Init()</code>: Expliziter synchroner Rücksprung (Reply Message) nach Abschluss der Initialisierungsroutine an <code>EcuM</code>.\n</li><li><code>Det_Start()</code>: Synchrone Startfunktion zur Aktivierung des regulären Tracing-Betriebs, aufgerufen von <code>EcuM</code> an <code>Det</code>.\n</li><li><code>Det_Start()</code>: Expliziter synchroner Rücksprung (Reply Message) an <code>EcuM</code>.\n</li></ul>\n<p class=\"fig-p\">Annotationen:</p>\n<ul class=\"fig-list\"><li>UML-Kommentar an <code>Det_Init()</code>: „Comment: Initialization of Default Error Tracer is performed synchronously“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Streng sequenzieller, synchroner Ablauf während des BSW-Hochlaufs:</p>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt den synchronen Aufruf <code>Det_Init()</code> an das Modul <code>Det</code> ab.\n</li><li><code>Det</code> aktiviert seinen Ausführungsfokus und führt die interne Modulinitialisierung blockierend/synchron aus.\n</li><li>Nach Beendigung kehrt der Kontrollfluss über die Reply-Nachricht von <code>Det_Init()</code> zu <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft anschließend synchron <code>Det_Start()</code> auf <code>Det</code> auf.\n</li><li><code>Det</code> aktiviert erneut seinen Ausführungsfokus zur Scharfschaltung des DET-Betriebs.\n</li><li>Über den Reply-Pfeil von <code>Det_Start()</code> kehrt die Kontrolle synchron an <code>EcuM</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich ist die zweistufige Reihenfolge der Initialisierung: Vor dem operativen Start (<code>Det_Start</code>) muss zwingend die Initialisierung (<code>Det_Init</code>) vollständig und synchron abgeschlossen sein. Die synchrone Abwicklung stellt sicher, dass der Default Error Tracer einsatzbereit ist, bevor nachfolgende BSW-Module initialisiert werden und Entwicklungsfehler (<code>Det_ReportError</code>) melden können. Da der Aufruf im EcuM-Startup-Pfad blockierend erfolgt, dürfen <code>Det_Init</code> und <code>Det_Start</code> keine zeitintensiven Hardware-Operationen oder Polling-Schleifen ausführen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1da64a4280390687", "to": "FIG-2a36d47c907298b4", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-2a36d47c907298b4", "to": "FIG-daca0b775c773d4c", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
